                    "sql": "create or replace table MAPLEMONK.CC_AMAZON_SALES_COST as with SKUMASTER AS ( select azp_asin as product_id ,azp_stock_code as common_sku_code ,azp_product_name name ,brand ,product_category category ,product_sub_category sub_category from `powerbi-425707.cc_comfort_db.amazon_product_map` map left join ( select sku_code,product_name_final,product_category,product_sub_category,brand from maplemonk.cc_sales_consolidated qualify row_number() over(partition by sku_code order by sku_code) = 1 )amz on cast(map.azp_stock_code as string) = cast(amz.sku_code as string) qualify row_number() over(partition by azp_asin order by azp_asin) = 1 ), sellerCentralSales as ( select cast(order_date as date) Date ,\'AMAZON\' marketplace ,Region ,sc.brand ,sm.product_id ASIN ,count(distinct order_id) SC_Orders ,sum(ifnull(quantity,0)) SC_Units ,sum(ifnull(quantity,0)) as sc_child_units ,sum(ifnull(sc.selling_price,0)) as Total_Sales ,sum(ifnull(sc.tax,0)) as tax ,sum(ifnull(sc.discount,0)) as discount from maplemonk.cc_sales_consolidated sc left join SKUMASTER sm on lower(sc.sku) = lower(sm.common_sku_code) where lower(order_status) not in (\'cancelled\') and lower(marketplace) like \'%amazon%\' group by cast(order_date as date) ,upper(shop_name) ,sm.product_id,region,sc.brand ), sellerCentralSessions as ( SELECT CAST(DATAENDTIME AS DATE) AS Date, \'AMAZON\' AS Marketplace, Country Region, asm.brand, parentasin AS ASIN, CAST(JSON_EXTRACT_SCALAR(salesbyasin, \'$.orderedProductSales.currencyCode\') AS string) AS currencyCode, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.browserPageViews\') AS INT64), 0)) AS Browser_Page_Views, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.browserSessions\') AS INT64), 0)) AS Browser_Sessions, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.buyBoxPercentage\') AS FLOAT64), 0)) AS BuyBox_Percentage, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.mobileAppPageViews\') AS INT64), 0)) AS MobileApp_Page_Views, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.mobileAppSessions\') AS INT64), 0)) AS MobileApp_Sessions, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.pageViews\') AS INT64), 0)) AS Page_Views, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(trafficbyasin, \'$.sessions\') AS INT64), 0)) AS Sessions, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(salesbyasin, \'$.unitsOrdered\') AS FLOAT64), 0)) AS SC_UnitsOrdered, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(salesbyasin, \'$.totalOrderItems\') AS FLOAT64), 0)) AS SC_ItemsOrdered, SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(salesbyasin, \'$.orderedProductSales.amount\') AS FLOAT64), 0)) AS SC_Sales FROM `maplemonk.CC_BR_Consolidated_GET_SALES_AND_TRAFFIC_REPORT_ASIN` sc left join SKUMASTER asm on lower(sc.parentasin) = lower(asm.product_id) GROUP BY CAST(DATAENDTIME AS DATE), Marketplace, parentasin,Country,currencyCode,asm.brand ), SellerCentralSpends as ( select mc.* ,coalesce(mp.brand,case when lower(replace(split(CAMPAIGNNAME,\'|\')[0],\' \',\'\')) like \'%weightworld%\' then \'WeightWorld\' when lower(replace(split(CAMPAIGNNAME,\'|\')[0],\' \',\'\')) like \'%maxmedix%\' then \'MaxMedix\' when lower(replace(split(CAMPAIGNNAME,\'|\')[0],\' \',\'\')) like \'%animigo%\' then \'Animigo\' when lower(replace(split(CAMPAIGNNAME,\'|\')[0],\' \',\'\')) like \'%mysmile%\' then \'Mysmile\' when lower(replace(split(CAMPAIGNNAME,\'|\')[0],\' \',\'\')) like \'%ecomasters%\' then \'Eco Masters\' else \'Others\' end) as Brand ,(ifnull(mc.ATTRIBUTED_SALES_14D,0)/ifnull(rh.er_exchange_rate,1)) as ATTRIBUTED_SALES_14D_GBP ,(ifnull(mc.spend,0)/ifnull(rh.er_exchange_rate,1)) as spend_gbp from maplemonk.cc_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED mc left join `cc_comfort_db.exchange_rate_history` rh on cast(rh.er_date as date) = cast(Date as date) and upper(mc.currency) = upper(rh.er_currency_name) left join SKUMASTER mp on lower(mc.ASIN) = lower(mp.product_id) ) select coalesce(sellerCentralSales.DATE, sellerCentralSessions.DATE, amazonads.date) Date ,\'Amazon\' Marketplace ,upper(coalesce(sellerCentralSales.region,sellerCentralSessions.region,amazonads.countryCode)) as Region ,coalesce(sellerCentralSales.ASIN, sellerCentralSessions.ASIN, amazonads.asin) ASIN ,coalesce(sellerCentralSales.brand, sellerCentralSessions.brand, amazonads.brand) Brand ,SKUMASTER.common_sku_code ,upper(SKUMASTER.NAME) Product_Name_Final ,upper(SKUMASTER.CATEGORY) Mapped_Product_Category ,upper(SKUMASTER.SUB_CATEGORY) Mapped_Sub_Category ,ifnull(sellerCentralSales.SC_Orders,0) SC_Orders ,ifnull(sellerCentralSales.SC_Units,0) SC_Units ,ifnull(sellerCentralSales.sc_child_units,0) sc_child_units ,ifnull(sellerCentralSales.Total_Sales,0) SC_Sales ,ifnull(sellerCentralSales.tax,0) SC_Tax ,ifnull(sellerCentralSales.Discount,0) SC_Discount ,ifnull(sellerCentralSessions.Sessions,0) SC_Sessions ,ifnull(sellerCentralSessions.Page_Views,0) SC_Page_Views ,ifnull(sellerCentralSessions.SC_UnitsOrdered,0) SC_UnitsOrdered_Traffic_report ,ifnull(sellerCentralSessions.SC_Sales,0) SC_Sales_Traffic_Report ,ifnull(sellerCentralSessions.Browser_Sessions,0) SC_Browser_Sessions ,ifnull(sellerCentralSessions.Browser_Page_Views,0) SC_Browser_Page_Views ,ifnull(sellerCentralSessions.MobileApp_Page_Views,0) SC_MobileApp_Page_Views ,ifnull(sellerCentralSessions.MobileApp_Sessions,0) SC_MobileApp_Sessions ,ifnull(sellerCentralSessions.BuyBox_Percentage,0) SC_BuyBox_Percentage ,ifnull(amazonads.SPEND_GBP,0) TOTAL_AD_SPEND_SESSION_SHARE ,ifnull(amazonads.ATTRIBUTED_SALES_14D_GBP,0) TOTAL_AD_SALES_SESSION_SHARE ,ifnull(amazonads.impressions,0) TOTAL_IMPRESSIONS_SESSION_SHARE ,ifnull(amazonads.clicks,0) TOTAL_CLICKS_SESSION_SHARE ,ifnull(amazonads.ATTRIBUTED_CONVERSIONS_14D,0) TOTAL_AD_CONVERSIONS_SESSION_SHARE ,case when AD_TYPE_1=\'SPONSORED BRANDS\' then ifnull(amazonads.spend_GBP,0) end BRAND_AD_SPEND_SESSION_SHARE ,case when AD_TYPE_1=\'SPONSORED DISPLAY\' then ifnull(amazonads.spend_GBP,0) end DISPLAY_AD_SPEND ,case when AD_TYPE_1=\'SPONSORED PRODUCT\' then ifnull(amazonads.spend_GBP,0) end PRODUCTS_AD_SPEND ,case when AD_TYPE_1=\'SPONSORED BRANDS\' then ifnull(amazonads.impressions,0) end BRAND_IMPRESSIONS ,case when AD_TYPE_1=\'SPONSORED DISPLAY\' then ifnull(amazonads.impressions,0) end DISPLAY_IMPRESSIONS ,case when AD_TYPE_1=\'SPONSORED PRODUCT\' then ifnull(amazonads.impressions,0) end PRODUCTS_IMPRESSIONS ,case when AD_TYPE_1=\'SPONSORED BRANDS\' then ifnull(amazonads.clicks,0) end BRAND_CLICKS ,case when AD_TYPE_1=\'SPONSORED DISPLAY\' then ifnull(amazonads.clicks,0) end DISPLAY_CLICKS ,case when AD_TYPE_1=\'SPONSORED PRODUCT\' then ifnull(amazonads.clicks,0) end PRODUCTS_CLICKS ,case when AD_TYPE_1=\'SPONSORED BRANDS\' then ifnull(amazonads.ATTRIBUTED_CONVERSIONS_14D,0) end BRAND_AD_CONVERSIONS ,case when AD_TYPE_1=\'SPONSORED DISPLAY\' then ifnull(amazonads.ATTRIBUTED_CONVERSIONS_14D,0) end DISPLAY_AD_CONVERSIONS ,case when AD_TYPE_1=\'SPONSORED PRODUCT\' then ifnull(amazonads.ATTRIBUTED_CONVERSIONS_14D,0) end PRODUCTS_AD_CONVERSIONS ,case when AD_TYPE_1=\'SPONSORED BRANDS\' then ifnull(amazonads.ATTRIBUTED_SALES_14D_GBP,0) end BRAND_AD_SALES ,case when AD_TYPE_1=\'SPONSORED DISPLAY\' then ifnull(amazonads.ATTRIBUTED_SALES_14D_GBP,0) end DISPLAY_AD_SALES ,case when AD_TYPE_1=\'SPONSORED PRODUCT\' then ifnull(amazonads.ATTRIBUTED_SALES_14D_GBP,0) end PRODUCTS_AD_SALES from sellerCentralSales full outer join sellerCentralSessions on sellerCentralSales.ASIN = sellerCentralSessions.ASIN and sellerCentralSales.date = sellerCentralSessions.date and lower(sellerCentralSales.region) = lower(sellerCentralSessions.region) and lower(sellerCentralSales.brand) = lower(sellerCentralSessions.brand) full outer join SellerCentralSpends amazonads on coalesce(sellerCentralSales.ASIN,sellerCentralSessions.ASIN) = amazonads.ASIN and coalesce(sellerCentralSales.date,sellerCentralSessions.date) = amazonads.date and lower(coalesce(sellerCentralSales.region,sellerCentralSessions.region)) = lower(amazonads.countryCode) and lower(coalesce(sellerCentralSales.brand,sellerCentralSessions.brand)) = lower(amazonads.brand) left join SKUMASTER on coalesce(sellerCentralSales.ASIN,sellerCentralSessions.ASIN, amazonads.ASIN) = SKUMASTER.product_id;",
                    "transaction": true
